{
  "ledger": {
    "p38:e257": {
      "state": "represented",
      "fact_ids": ["P0038F0001"],
      "note": "적용 대상(1번 network_forward 중간 복사 제거)이 사실에 보존됨"
    },
    "p38:e258": {
      "state": "unresolved",
      "fact_ids": ["P0038F0002", "P0038F0015"],
      "note": "원문은 '여 기서 바꾸는 과정에 주목할 부분'이라는 제목뿐이나, 승인된 사실 P0038F0002와 P0038F0015에 e259의 내용(net.act[l] 사용, 메모리풀 미관리)이 잘못 귀속됨. e258 자체의 '바꾸는 과정 주목'이라는 의미만으로는 불충분하게 표현됨"
    },
    "p38:e259": {
      "state": "represented",
      "fact_ids": ["P0038F0002", "P0038F0009"],
      "note": "net.act[l] 사용 및 메모리풀 미관리 내용이 사실에 보존됨. 단 P0038F0002는 e258에도 중복 귀속되어 있어 분리 필요"
    },
    "p38:e260": {
      "state": "represented",
      "fact_ids": ["P0038F0017"],
      "note": "gemini에 따르면이라는 출처 표기가 사실에 보존됨"
    },
    "p38:e261": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "CPU가 net.act[l]의 포인터가 아닌 값(Relu면 0, Sigmoid면 1)을 읽어 Constant Memory/Registers에 넣어 GPU로 전달한다는 핵심 설명이 승인된 사실에 전혀 보존되지 않음"
    },
    "p38:e262": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "ActivationType이 단순한 enum(내부적으로 4바이트 정수)이라는 사실이 승인된 사실에 보존되지 않음"
    },
    "p38:e263": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "cudaMalloc/cudaMemcpy 불필요, 커널 런칭 시 값 자동 GPU 전달, 속도 저하 없음, 큰 배열/구조체는 포인터로 cudaMemcpy 후 주소 전달이라는 설명이 승인된 사실에 보존되지 않음"
    },
    "p38:e264": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "큰 덩어리는 포인터로, 작은 숫자/Enum은 값으로 전달 가능하다는 요약이 승인된 사실에 보존되지 않음"
    },
    "p38:e265": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "'좀 더 정확히 설명해보자'라는 전환 문장이 승인된 사실에 보존되지 않음"
    },
    "p38:img0:e0": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "코드 주석 '// 3. GPU 내부에서 활성화 함수 적용'이 승인된 사실에 보존되지 않음"
    },
    "p38:img0:e1": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "코드 주석 '// 여기서 CPU 메모리에 있는 net.act[1] 를 사용했는데, CUDA 커널 인자 방식을 이해해야함'이 승인된 사실에 보존되지 않음"
    },
    "p38:img0:e2": {
      "state": "unresolved",
      "fact_ids": [],
      "note": "코드 'apply_activation_gpu<<blocksPerGrid, 256>>>(net.act[1], d_out);'가 승인된 사실에 보존되지 않음"
    }
  }
}
